// Macro density index — record JAH-GPCS-MACROPAD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"keys": 15, "layers": 10, "price_usd": 150};
var value = (m.keys*m.layers/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-MACROPAD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-MACROPAD-000001|' + value.toFixed(2) + ' density index');

